class InsufficientFundsError(Exception):
    pass


class Money:  # Value Object
    def __init__(self, amount: int, currency: str = "USD"):
        if amount < 0:
            raise ValueError("Сумма не может быть отрицательной")
        self.amount = amount
        self.currency = currency

    def __add__(self, other):
        if self.currency != other.currency:
            raise ValueError("Разные валюты")
        return Money(self.amount + other.amount, self.currency)

    def __sub__(self, other):
        if other.amount > self.amount:
            raise InsufficientFundsError(f"Недостаточно средств: {self.amount} < {other.amount}")
        return Money(self.amount - other.amount, self.currency)

    def __eq__(self, other):
        return isinstance(other, Money) and self.amount == other.amount and self.currency == other.currency

    def __repr__(self):
        return f"Money({self.amount}, '{self.currency}')"


class Account:  # Aggregate Root, Entity
    def __init__(self, account_id: int, balance: Money):
        self.id = account_id
        self._balance = balance
        self._history = []

    def withdraw(self, amount: Money):
        self._balance = self._balance - amount   # __sub__ бросит InsufficientFundsError сам
        self._history.append(("withdraw", amount))

    def deposit(self, amount: Money):
        self._balance = self._balance + amount
        self._history.append(("deposit", amount))

    @property
    def balance(self):
        return self._balance


