class BaseItemRepository:
    def __init__(self):
        self.items = {}
        self.skus = set()
    def create(self, item: dict) -> dict:
        iid = item['id']
        sku = item['sku']
        if iid in self.items:
            raise DuplicateKeyError('Duplicate key: id')
        if sku in self.skus:
            raise DuplicateKeyError('Duplicate key: sku')
        self.items[iid] = dict(item)
        self.skus.add(sku)
        return dict(item)
    def delete(self, item_id: str) -> bool:
        if item_id in self.items:
            removed = self.items.pop(item_id)
            self.skus.discard(removed['sku'])
            return True
        return False
    def exists(self, item_id: str) -> bool:
        return item_id in self.items

