class OrderRepository:
    def __init__(self, data_source):
        self.source = data_source
        self.batch_calls = 0
    def _fetch_batch(self, unique_ids: set) -> dict:
        self.batch_calls += 1
        return {uid: self.source[uid] for uid in unique_ids if uid in self.source}
    def get_by_ids_ordered(self, ids: list) -> list:
        unique_ids = set(ids)
        batch_map = self._fetch_batch(unique_ids) if unique_ids else {}
        return [batch_map.get(i) for i in ids]

