class UnitOfWork:
    def __init__(self, storage: dict):
        self.storage = storage
        self._new = {}
        self._dirty = {}
        self._deleted = set()
    def register_new(self, entity: dict):
        self._new[entity['id']] = dict(entity)
    def register_dirty(self, entity: dict):
        self._dirty[entity['id']] = dict(entity)
    def register_deleted(self, entity_id: str):
        self._deleted.add(entity_id)
    def commit(self):
        for eid, ent in self._new.items():
            self.storage[eid] = dict(ent)
        for eid, ent in self._dirty.items():
            self.storage[eid] = dict(ent)
        for eid in self._deleted:
            self.storage.pop(eid, None)
        self.rollback()
    def rollback(self):
        self._new.clear()
        self._dirty.clear()
        self._deleted.clear()

